List<String> parallelAnswer = byParallelSafe(many);
checkEq(parallelAnswer, byLoop(many));
checkEq(parallelAnswer.size(), 2);
checkEq(parallelAnswer.get(0), "even: 2500 readings, min 0, max 4998, mean 2499.00");

